const staticData = $getWorkflowStaticData('global');
staticData.chats = staticData.chats || {};

const item = $input.all()[0].json;
const chatId = item.message.chat.id;
const text = item.message.text || '';

// Si el usuario escribe /start o algo para reiniciar, limpiamos memoria
if (text.toLowerCase() === '/start' || text.toLowerCase() === 'reiniciar') {
  staticData.chats[chatId] = [];
}

// Inicializar historial para el usuario si no existe
if (!staticData.chats[chatId] || staticData.chats[chatId].length === 0) {
  const systemPrompt = `Eres Fisioterapeuta Li, un asistente amigable por Telegram.
Tu objetivo es agendar citas.

Para agendar, DEBES recolectar OBLIGATORIAMENTE 4 datos:
1. nombre
2. fecha (siempre en formato YYYY-MM-DD)
3. hora (siempre en formato HH:MM)
4. servicio (ej: Terapia Manual, Masaje)

RESPONDE ÚNICAMENTE CON UN JSON VÁLIDO en este formato:
{
  "estado": "pedir_datos" | "pedir_confirmacion" | "ejecutar_reserva",
  "mensaje_usuario": "...",
  "datos": {
    "nombre": "",
    "fecha": "",
    "hora": "",
    "servicio": ""
  }
}

REGLAS DE ESTADO:
- 'pedir_datos': Si falta ALGÚN dato. En 'mensaje_usuario' hazle una pregunta corta y amable pidiendo lo que falta. Trata de no pedir todo de golpe si falta mucho.
- 'pedir_confirmacion': SI YA TIENES LOS 4 DATOS, pero el usuario no ha confirmado. En 'mensaje_usuario' dile: 'Tengo todo listo para agendar tu cita para [Servicio] el [Fecha] a las [Hora] a nombre de [Nombre]. ¿Confirmas la reserva?'.
- 'ejecutar_reserva': SOLO si estabas en 'pedir_confirmacion' y el usuario acaba de responder 'Sí', 'Confirmo', 'Ok' o similar. En 'mensaje_usuario' pon 'Procesando tu reserva...'.

REGLAS DE DATOS:
- Mantén siempre en el JSON los datos que ya hayas recolectado en el historial.
- Convierte fechas a YYYY-MM-DD y horas a HH:MM.`;

  staticData.chats[chatId] = [{ role: 'system', content: systemPrompt }];
}

// Limitar historial a los últimos 15 mensajes para no saturar a Ollama
if (staticData.chats[chatId].length > 15) {
  // Mantener el system prompt (index 0) y los últimos 14
  staticData.chats[chatId] = [staticData.chats[chatId][0], ...staticData.chats[chatId].slice(-14)];
}

// Agregar mensaje del usuario
staticData.chats[chatId].push({ role: 'user', content: text });

return [{ json: { chatId: chatId, messages: staticData.chats[chatId] } }];

const staticData = $getWorkflowStaticData('global');
const item = $input.all()[0].json;
const chatId = $('Preparar Memoria (StaticData)').first().json.chatId;
const responseText = item.message.content;

// Guardar la respuesta de la IA en el historial (como un string JSON)
if (staticData.chats && staticData.chats[chatId]) {
  staticData.chats[chatId].push({ role: 'assistant', content: responseText });
}

let parsed;
try {
  let cleanText = responseText.replace(/^```json\n?/i, '').replace(/```$/,'').trim();
  parsed = JSON.parse(cleanText);
} catch(e) {
  parsed = {
    estado: 'pedir_datos',
    mensaje_usuario: 'Tuve un pequeño problema técnico procesando tu mensaje. ¿Me lo repites por favor?',
    datos: {}
  };
}

return [{ json: {
  chatId: chatId,
  estado: parsed.estado || 'pedir_datos',
  mensaje_usuario: parsed.mensaje_usuario || 'Procesado.',
  datos: parsed.datos || {}
}}];

